SELECT ?dougLimanBirthDate ?director ?directorBirthDate WHERE {
  ?dougLiman a dbo:Person ;
             foaf:name "Douglas Eric Liman"@en ;
             dbo:birthDate ?dougLimanBirthDate .
  ?director a dbo:Person ;
            dbo:occupation dbo:FilmDirector ;
            dbo:birthDate ?directorBirthDate .
  ?chrisRichmond a dbo:Person ;
                foaf:name "Chris Richmond"@en ;
                dbo:knownFor ?work .
  ?director dbo:director ?work .
  FILTER (?dougLimanBirthDate < ?directorBirthDate)
}
LIMIT 1

