SELECT ?julienActs ?roiMalgreLuiActs ?isSequel WHERE {
  ?julienOpera rdfs:label "Julien"@en .
  ?julienOpera wdt:P31 wd:Q134428 ;  # instance of opera
                wdt:P86 ?composerJulien ;
                wdt:P527 ?julienParts .
  ?julienParts wdt:P3608 ?julienActsCount .
  BIND(xsd:integer(?julienActsCount) AS ?julienActs)

  ?roiOpera rdfs:label "Le roi malgré lui"@fr .
  ?roiOpera wdt:P31 wd:Q134428 ;
           wdt:P527 ?roiParts .
  ?roiParts wdt:P3608 ?roiActsCount .
  BIND(xsd:integer(?roiActsCount) AS ?roiMalgreLuiActs)

  OPTIONAL {
    ?julienOpera wdt:P144 ?prequelOpera .
    ?prequelOpera rdfs:label ?prequelLabel .
    FILTER(CONTAINS(LCASE(?prequelLabel), "julien") || CONTAINS(LCASE(?prequelLabel), "julien"))
  }

  BIND(IF(BOUND(?prequelOpera), true, false) AS ?isSequel)
}
LIMIT 1

