SELECT ?company ?companyLabel ?terminus ?terminusLocationLabel WHERE {
  ?station wdt:P31 wd:Q55488;  # instance of railway station
           rdfs:label "Quaker Ridge"@en;
           wdt:P127 ?company.  # owned by company

  ?company wdt:P31 wd:Q4830453; # instance of railway company (assuming proper class)
           wdt:P136 ?railway;  # associated railway
           wdt:P795 ?terminus. # has terminus

  ?terminus wdt:P131 ?terminusLocation.
  ?terminusLocation wdt:P131* wd:Q1121. # located in Westchester County (Q1121 is Westchester)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

LIMIT 10

SELECT ?person ?occupation WHERE {
  { 
    ?person wdt:P31 wd:Q5;       # instance of human
            wdt:P106 wd:Q2526255; # occupation film director
            rdfs:label "Ettore Scola"@en.
  }
  UNION
  {
    ?film rdfs:label "Che strano chiamarsi Federico"@it.
    ?film wdt:P58 ?person.        # director or co-writer of the film
    ?person wdt:P106 ?occupation.
    FILTER EXISTS {
      ?person wdt:P800 ?work.
      ?work rdfs:label "Yes Minister"@en.
    }
  }
}

SELECT ?person WHERE {
  ?film1 wdt:P31 wd:Q11424;        # Finding Dory is a film
         rdfs:label "Finding Dory"@en;
         wdt:P57 ?directorFindingDory.  # Director of Finding Dory
